using System;using System.Collections;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;
namespace SokobanStudio {
public static class Navigation {public static string Selected;public static bool SelectPage;static PresetProgress progress;public static PresetProgress Progress{get=>progress??(progress=new PresetProgress(System.IO.Path.Combine(Application.persistentDataPath,"preset-progress.json")));set=>progress=value;}public static readonly string[] Names={"First Delivery","The Wrong Shortcut","Dual Crate Dispatch","Two Targets","Cargo Routing","Loop Corridor","Making Room","Final Dispatch","Split Warehouses","Offset Dispatch","Shifted Aisle","Winding Return","Narrow Passage","Six Crate Dispatch","Seven Crate Matrix"};public static void Play(int n){if(!Progress.Unlocked(n))return;Selected=PresetProgress.Id(n);SceneManager.LoadScene("Game");}public static void Menu(bool select=false){Selected=null;SelectPage=select;SceneManager.LoadScene("MainMenu");}[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]static void Reset(){progress=null;Selected=null;SelectPage=false;}}
public static class StudioUI {
 public const float ControlHeight=36;public const int BodySize=18,HeadingSize=28,Gap=12;public static readonly Color Ink=new Color(.88f,.94f,1),Success=new Color(.35f,.85f,.6f),Warning=new Color(1,.65f,.35f),Background=new Color(.035f,.055f,.09f),PanelColor=new Color(.085f,.125f,.19f),Accent=new Color(.15f,.55f,.9f);static Sprite rounded;
 public static Sprite Rounded{get{if(rounded)return rounded;var t=new Texture2D(32,32);for(int y=0;y<32;y++)for(int x=0;x<32;x++){float dx=Mathf.Max(0,Mathf.Abs(x-15.5f)-8),dy=Mathf.Max(0,Mathf.Abs(y-15.5f)-8);t.SetPixel(x,y,new Color(1,1,1,Mathf.Clamp01(8-Mathf.Sqrt(dx*dx+dy*dy))));}t.Apply();rounded=Sprite.Create(t,new Rect(0,0,32,32),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect,new Vector4(9,9,9,9));return rounded;}}
 public static Canvas Canvas(Transform parent){FeedbackAudio.Ensure(parent);if(!parent.Find("Screen Clear Camera")){var gcam=new GameObject("Screen Clear Camera",typeof(Camera));gcam.transform.SetParent(parent,false);var cam=gcam.GetComponent<Camera>();cam.depth=-100;cam.cullingMask=0;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Background;cam.rect=new Rect(0,0,1,1);cam.orthographic=true;}var g=new GameObject("Studio UI",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));g.transform.SetParent(parent,false);var c=g.GetComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;var s=g.GetComponent<CanvasScaler>();s.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;s.referenceResolution=new Vector2(1280,720);s.screenMatchMode=CanvasScaler.ScreenMatchMode.Expand;if(!EventSystem.current)new GameObject("EventSystem",typeof(EventSystem),typeof(StandaloneInputModule)).transform.SetParent(parent);EventSystem.current.sendNavigationEvents=false;return c;}
 public static RectTransform Rect(Transform p,string name,Vector2 min,Vector2 max,Vector2 inset){var g=new GameObject(name,typeof(RectTransform));var r=g.GetComponent<RectTransform>();r.SetParent(p,false);r.anchorMin=min;r.anchorMax=max;r.offsetMin=inset;r.offsetMax=-inset;return r;}
 public static RectTransform Panel(Transform p,string name,Vector2 min,Vector2 max,Color color){var r=Rect(p,name,min,max,Vector2.zero);r.gameObject.AddComponent<Image>().color=color;return r;}
 public static Text Text(Transform p,string value,int size=22){var r=Rect(p,"Text",Vector2.zero,Vector2.one,new Vector2(12,6));var t=r.gameObject.AddComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.fontSize=size;t.lineSpacing=1.15f;t.color=Ink;t.text=value;t.alignment=TextAnchor.MiddleCenter;t.raycastTarget=false;return t;}
 public static void Size(GameObject g,float height,float width=-1){var l=g.AddComponent<LayoutElement>();l.minHeight=l.preferredHeight=height;if(width>0)l.minWidth=l.preferredWidth=width;else l.flexibleWidth=1;}
 public static VerticalLayoutGroup Column(RectTransform r,int padding=20){var v=r.gameObject.AddComponent<VerticalLayoutGroup>();v.padding=new RectOffset(padding,padding,padding,padding);v.spacing=12;v.childControlHeight=true;v.childForceExpandHeight=false;v.childControlWidth=v.childForceExpandWidth=true;return v;}
 public static Text RowText(Transform p,string value,int size=22,float height=40){var t=Text(p,value,size);Size(t.gameObject,height);return t;}
 public static void Style(Button b){var navigation=b.navigation;navigation.mode=UnityEngine.UI.Navigation.Mode.None;b.navigation=navigation;var surface=b.GetComponent<Image>();surface.sprite=Rounded;surface.type=Image.Type.Sliced;var c=b.colors;c.normalColor=PanelColor*1.7f;c.highlightedColor=Accent;c.pressedColor=new Color(.1f,.32f,.55f);c.selectedColor=new Color(.18f,.4f,.62f);c.disabledColor=new Color(.11f,.14f,.19f);c.fadeDuration=.08f;b.colors=c;b.targetGraphic.color=Color.white;}
 public static Button Button(Transform p,string title,Action action,float height=ControlHeight){var r=Rect(p,title,Vector2.zero,Vector2.one,Vector2.zero);r.gameObject.AddComponent<Image>();var b=r.gameObject.AddComponent<Button>();Style(b);Text(r,title,BodySize);Size(r.gameObject,height);b.onClick.AddListener(()=>{FeedbackAudio.Play("click");action();});return b;}
 public static RectTransform Modal(Transform p,string title){var shade=Panel(p,"Modal",Vector2.zero,Vector2.one,new Color(0,0,0,.78f));var card=Panel(shade,"Dialog",new Vector2(.27f,.12f),new Vector2(.73f,.88f),PanelColor);Column(card,24);RowText(card,title,28,54);shade.gameObject.AddComponent<ModalAppear>();return card;}
 public static void Remove(GameObject g){if(g){g.SetActive(false);UnityEngine.Object.Destroy(g);}}
}
public class ModalAppear:MonoBehaviour{IEnumerator Start(){var c=gameObject.AddComponent<CanvasGroup>();var child=transform.GetChild(0);float t=0;while(t<.18f){t+=Time.unscaledDeltaTime;c.alpha=Mathf.Clamp01(t/.18f);child.localScale=Vector3.one*Mathf.Lerp(.94f,1,c.alpha);yield return null;}c.alpha=1;child.localScale=Vector3.one;}}
public class MainMenuController:MonoBehaviour {
 Canvas canvas;GameObject page;RectTransform grid;int levelPage;
 void Start(){canvas=StudioUI.Canvas(transform);if(Navigation.SelectPage)Levels();else Home();}
 void Clear(){StudioUI.Remove(page);page=StudioUI.Panel(canvas.transform,"Page",Vector2.zero,Vector2.one,StudioUI.Background).gameObject;grid=null;}
 void Home(){Clear();page.AddComponent<WarehouseBackdrop>();var title=StudioUI.Rect(page.transform,"Game Title",new Vector2(.12f,.65f),new Vector2(.88f,.9f),Vector2.zero);var heading=StudioUI.Text(title,"SOKOBAN\nSTUDIO",64);heading.fontStyle=FontStyle.Bold;heading.lineSpacing=.85f;StudioUI.Text(StudioUI.Rect(page.transform,"Subtitle",new Vector2(.2f,.57f),new Vector2(.8f,.64f),Vector2.zero),"ROBOT WAREHOUSE / EVERY CRATE HAS A PLACE",17);StudioUI.Panel(page.transform,"Title Rule",new Vector2(.39f,.555f),new Vector2(.61f,.558f),StudioUI.Accent).GetComponent<Image>().raycastTarget=false;var menu=StudioUI.Rect(page.transform,"Menu Actions",new Vector2(.36f,.22f),new Vector2(.64f,.49f),Vector2.zero);StudioUI.Column(menu,8);StudioUI.Button(menu,"Start Game",Levels,46);StudioUI.Button(menu,"Level Editor",()=>SceneManager.LoadScene("LevelEditor"),46);StudioUI.Button(menu,"Quit",()=>Application.Quit(),46);StudioUI.Text(StudioUI.Rect(page.transform,"Footer",new Vector2(.2f,.035f),new Vector2(.8f,.09f),Vector2.zero),"SOKOBAN STUDIO / WAREHOUSE OPERATIONS",14);}
 void Levels(){Clear();StudioUI.Text(StudioUI.Rect(page.transform,"Header",new Vector2(.05f,.87f),new Vector2(.95f,.98f),Vector2.zero),"WAREHOUSE ASSIGNMENTS",30);grid=StudioUI.Rect(page.transform,"Cards",new Vector2(.06f,.18f),new Vector2(.94f,.85f),Vector2.zero);var layout=grid.gameObject.AddComponent<GridLayoutGroup>();layout.spacing=new Vector2(16,16);layout.constraint=GridLayoutGroup.Constraint.FixedColumnCount;for(int n=levelPage*8+1;n<=Mathf.Min((levelPage+1)*8,PresetProgress.LevelCount);n++){int index=n;var b=StudioUI.Button(grid,"",()=>Navigation.Play(index));b.interactable=Navigation.Progress.Unlocked(n);StudioUI.Remove(b.GetComponentInChildren<Text>().gameObject);StudioUI.Text(StudioUI.Rect(b.transform,"Assignment",new Vector2(0,.8f),Vector2.one,Vector2.zero),n.ToString("00")+"  "+Navigation.Names[n-1],17);LevelPreview.Attach(StudioUI.Rect(b.transform,"Preview Area",new Vector2(.08f,.22f),new Vector2(.92f,.77f),Vector2.zero),LevelJson.Load(Resources.Load<TextAsset>("PresetLevels").text,PresetProgress.Id(n)));StudioUI.Text(StudioUI.Rect(b.transform,"State",Vector2.zero,new Vector2(1,.2f),Vector2.zero),Navigation.Progress.Completed(n)?"[OK] COMPLETED":b.interactable?"AVAILABLE":"[LOCK] LOCKED",16);}var previous=StudioUI.Rect(page.transform,"Previous Page",new Vector2(.06f,.05f),new Vector2(.23f,.12f),Vector2.zero);StudioUI.Column(previous,0);StudioUI.Button(previous,"Previous",()=>{levelPage--;Levels();}).interactable=levelPage>0;var next=StudioUI.Rect(page.transform,"Next Page",new Vector2(.77f,.05f),new Vector2(.94f,.12f),Vector2.zero);StudioUI.Column(next,0);StudioUI.Button(next,"Next",()=>{levelPage++;Levels();}).interactable=(levelPage+1)*8<PresetProgress.LevelCount;var footer=StudioUI.Rect(page.transform,"Footer",new Vector2(.3f,.03f),new Vector2(.7f,.14f),Vector2.zero);StudioUI.Column(footer,0);StudioUI.Button(footer,"Back to Main Menu",Home);if(Navigation.Progress.Error!=null)StudioUI.RowText(footer,Navigation.Progress.Error,14,24);Resize();}
 void Resize(){if(!grid)return;int cols=Screen.width/(float)Screen.height<1.5f?2:4;var l=grid.GetComponent<GridLayoutGroup>();l.constraintCount=cols;l.cellSize=new Vector2((grid.rect.width-16*(cols-1))/cols,(grid.rect.height-16*(8/cols-1))/(8/cols));}void LateUpdate(){Resize();}
}
}

